def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            seen.add((r, c))
            q = deque([(r, c)])
            cells = [(r, c)]
            while q:
                y, x = q.popleft()
                for ny, nx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
                        cells.append((ny, nx))
